-- Replace the first 20 published Who Said It levels with passage-reviewed questions.
-- Existing row IDs and question_key values are intentionally preserved so player progress stays linked.
DO $$
DECLARE
  v_updated integer;
BEGIN
  UPDATE public.game_content AS gc
  SET question_text = v.question_text,
      options = v.options,
      correct_answer = v.correct_answer,
      explanation = v.explanation,
      "reference" = v.reference,
      metadata = v.metadata
  FROM (VALUES
(1,1,'"Thou God seest me."',ARRAY['Hagar','Sarah','Leah','Rebekah']::text[],'Hagar','Hagar named the LORD who spoke with her, declaring that He was the God who saw her.','Genesis 16:13','{"difficulty":"beginner","fact_key":"who-said-it-fact-1"}'::jsonb),
(1,2,'"Am I in the place of God?"',ARRAY['Joseph','Cain','Isaiah','Samuel']::text[],'Joseph','The biblical account in Genesis 50:19 supports this identification.','Genesis 50:19','{"difficulty":"beginner","fact_key":"who-said-it-fact-2"}'::jsonb),
(1,3,'"Shall not the Judge of all the earth do right?"',ARRAY['Abraham','Isaac','Jacob','Moses']::text[],'Abraham','Abraham appealed to God''s justice while interceding for Sodom.','Genesis 18:25','{"difficulty":"beginner","fact_key":"who-said-it-fact-3"}'::jsonb),
(1,4,'"I am not eloquent, neither heretofore, nor since thou hast spoken unto thy servant."',ARRAY['Moses','Aaron','Joshua','Gideon']::text[],'Moses','Moses raised his concern about his speaking ability when God called him to lead Israel.','Exodus 4:10','{"difficulty":"beginner","fact_key":"who-said-it-fact-4"}'::jsonb),
(1,5,'"How can I go? If Saul hear it, he will kill me."',ARRAY['Samuel','Cain','Joseph','Isaiah']::text[],'Samuel','The biblical account in 1 Samuel 16:2 supports this identification.','1 Samuel 16:2','{"difficulty":"beginner","fact_key":"who-said-it-fact-5"}'::jsonb),
(2,1,'"Thou art the man."',ARRAY['Nathan','Cain','Joseph','Isaiah']::text[],'Nathan','The biblical account in 2 Samuel 12:7 supports this identification.','2 Samuel 12:7','{"difficulty":"beginner","fact_key":"who-said-it-fact-6"}'::jsonb),
(2,2,'"Give therefore thy servant an understanding heart."',ARRAY['Solomon','Cain','Joseph','Isaiah']::text[],'Solomon','The biblical account in 1 Kings 3:9 supports this identification.','1 Kings 3:9','{"difficulty":"beginner","fact_key":"who-said-it-fact-7"}'::jsonb),
(2,3,'"The Lord, he is the God; the Lord, he is the God."',ARRAY['The people of Israel','Elijah','Ahab','The prophets of Baal']::text[],'The people of Israel','After the people saw the LORD answer by fire, the people fell on their faces and declared that the LORD is God.','1 Kings 18:39','{"difficulty":"beginner","fact_key":"who-said-it-fact-8"}'::jsonb),
(2,4,'Who instructed Gehazi to ask the Shunammite woman, \"Is it well with thee? is it well with thy husband? is it well with the child?\"?',ARRAY['Elisha','Cain','Joseph','Isaiah']::text[],'Elisha','Elisha instructed Gehazi to ask the Shunammite woman these questions.','2 Kings 4:26','{"difficulty":"beginner","fact_key":"who-said-it-fact-9"}'::jsonb),
(2,5,'"Let not your heart be troubled."',ARRAY['Jesus','Nehemiah','Paul','John the Baptist']::text[],'Jesus','Jesus spoke these words to His disciples as He comforted them before His arrest.','John 14:1','{"difficulty":"beginner","fact_key":"who-said-it-fact-10"}'::jsonb),
